CREATE TABLE inbox_items(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',done INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE INDEX idx_inbox_user ON inbox_items(user_id,done,created_at);
CREATE TABLE planner_slots(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,card_id TEXT REFERENCES cards(id) ON DELETE SET NULL,title TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX idx_planner_user ON planner_slots(user_id,start_at);
CREATE INDEX idx_planner_card ON planner_slots(card_id);
CREATE TABLE project_work_types(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL,color TEXT NOT NULL DEFAULT '#0d9488');
CREATE INDEX idx_work_types_project ON project_work_types(project_id);
CREATE TABLE card_productivity(card_id TEXT PRIMARY KEY REFERENCES cards(id) ON DELETE CASCADE,work_type_id TEXT REFERENCES project_work_types(id) ON DELETE SET NULL,repeat_days INTEGER,reminder_minutes INTEGER,reminded_for TEXT,last_occurrence TEXT);
CREATE INDEX idx_productivity_type ON card_productivity(work_type_id);
CREATE TABLE workflow_transitions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,from_column TEXT NOT NULL REFERENCES columns(id) ON DELETE CASCADE,to_column TEXT NOT NULL REFERENCES columns(id) ON DELETE CASCADE,name TEXT NOT NULL,require_description INTEGER NOT NULL DEFAULT 0,require_checklists INTEGER NOT NULL DEFAULT 0,require_approval INTEGER NOT NULL DEFAULT 0,allowed_role TEXT NOT NULL DEFAULT 'member',UNIQUE(project_id,from_column,to_column));
CREATE INDEX idx_workflow_project ON workflow_transitions(project_id);
CREATE INDEX idx_workflow_from ON workflow_transitions(from_column);
CREATE INDEX idx_workflow_to ON workflow_transitions(to_column);
CREATE TABLE card_approvals(id TEXT PRIMARY KEY,card_id TEXT NOT NULL REFERENCES cards(id) ON DELETE CASCADE,transition_id TEXT NOT NULL REFERENCES workflow_transitions(id) ON DELETE CASCADE,requested_by TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,approved_by TEXT REFERENCES users(id) ON DELETE SET NULL,requested_at TEXT NOT NULL,approved_at TEXT,revision TEXT NOT NULL,UNIQUE(card_id,transition_id,revision));
CREATE INDEX idx_approval_card ON card_approvals(card_id);
CREATE INDEX idx_approval_transition ON card_approvals(transition_id);
CREATE INDEX idx_approval_requested ON card_approvals(requested_by);
CREATE INDEX idx_approval_approved ON card_approvals(approved_by);
CREATE TABLE intake_forms(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,column_id TEXT NOT NULL REFERENCES columns(id) ON DELETE CASCADE,name TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,require_description INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE INDEX idx_intake_project ON intake_forms(project_id);
CREATE INDEX idx_intake_column ON intake_forms(column_id);
CREATE TABLE board_templates(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,name TEXT NOT NULL,data_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX idx_template_workspace ON board_templates(workspace_id);
CREATE TABLE card_status_history(id TEXT PRIMARY KEY,card_id TEXT NOT NULL REFERENCES cards(id) ON DELETE CASCADE,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,column_id TEXT NOT NULL REFERENCES columns(id) ON DELETE CASCADE,entered_at TEXT NOT NULL);
CREATE INDEX idx_status_card ON card_status_history(card_id,entered_at);
CREATE INDEX idx_status_project ON card_status_history(project_id,entered_at);
CREATE INDEX idx_status_column ON card_status_history(column_id);
